definition.raw:
Let  $H$ be the Friedrichs extension of $\overline Q_H$, $e^{-itH}$ the unitary group on $L^2(\R^n)$ generated by $H$ via Stone's theorem and $\Gamma_H$ the inhomogeneous propagator defined by
\begin{align}
\label{inhomogeneous_propagator}
\Gamma_HF(t)=\int_0^t e^{-i(t-s)H}F(s)ds,\quad F\in L^1_{\mathrm{loc}}(\R;L^2(\R^n)).

Let $\Gamma_H$ be the inhomogeneous propagator defined by the formula \eqref{inhomogeneous_propagator} and set
\begin{align}
\label{adjoint_1}
\Gamma_H^*F(t)=\mathds1_{[0,\infty)}(t)\int _t^Te^{-i(t-s)H}F(s)ds-\mathds1_{(-\infty,0]}(t)\int_{-T}^te^{-i(t-s)H}F(s)ds.

theorem.raw:
[{\cite[Theorem 1.2]{BDDLL}}]
\label{theorem_BDDLL}
Let $n\ge3$, $a\ge -(n-2)^2/4+1/4$ and $\ep>0$. Then there exists $C_\ep>0$ such that for all $\psi\in L^2(\R^n)$, $e^{-itH_a}\psi$ satisfies
\begin{align}
\label{theorem_BDDLL_1}
\norm{w(|x|)|D|^{1/2}e^{-itH_a}\psi}_{L^2(\R^{1+n})}\le C_\ep\norm{\psi}_{L^2(\R^n)}
\end{align}
where $w(r)=r^{(\ep-1)/2}(1+r^\ep)^{-1}$.

\label{theorem_2}
Let $n\ge3$, $\rho>1/2$ and $\A,\B\in \{\dot\H^{-1/2,\rho}(\R^n),\ L^{\frac{2n}{n+2},2}(\R^n)\}$.  Suppose $V$ satisfies Assumption \ref{assumption_A}. Then the solution $u$ to \eqref{equation} given by \eqref{solution} satisfies
\begin{align}
\label{theorem_2_1}
\norm{u}_{L^{2}(\R;\B^*)}\le C\norm{\psi}_{L^2(\R^n)}+C\norm{F}_{L^2(\R;\A)}
\end{align}
for all $\psi\in L^2(\R^n)$ and $F\in L^1_{\mathrm{loc}}(\R;L^2(\R^n)) \cap L^2(\R;\A)$.

