{BoMi}}]
\label{lemma_abstract_2}
Suppose that $A$ is $H$-smooth with bound $a$. Then $A\Gamma_H$ and $A\Gamma^*_H$ extend to bounded operators from $L^1_T\H$ to $L^2_T\H$ such that
\begin{align}
\label{lemma_abstract_2_1}
\norm{A\Gamma_HF}_{L^2_T\H}\le Ca\norm{F}_{L^1_T\H},\quad
\norm{A\Gamma_H^*F}_{L^2_T\H}\le Ca\norm{F}_{L^1_T\H}
\end{align}
for any $T>0$ and $F\in L^1_T\H$ with some $C>0$ independent of $a,T$ and $F$. Moreover, we have
\begin{align}
\label{lemma_abstract_2_2}
A\Gamma_HF(t)=\int_0^tAe^{-i(t-s)H}F(s)ds
\end{align}
for all simple function $F:[-T,T]\to \H$ and a.e. $t\in[-T,T]$. In particular $A\Gamma_HF(t)$ and $\int_0^tAe^{-i(t-s)H}F(s)ds$ coincide in $L^2_T\H$.

\label{lemma_proof_1}
There exists $C>0$ such that, for any $v\in L^{n,\infty}(\R^n)$ and $T>0$, 
\begin{align}
\label{lemma_proof_1_1}
\norm{e^{it\Delta}\psi}_{L^2_TL^{2^*,2}}&\le C\norm{\psi}_{L^2},\\
\label{lemma_proof_1_2}
\norm{\Gamma_0 F}_{L^2_TL^{2^*,2}}&\le C \norm{F}_{L^2_TL^{2_*,2}},\\
\label{lemma_proof_1_3}
\norm{v(x)\Gamma_0 F}_{L^2_TL^{2}}&\le C \norm{v}_{L^{n,\infty}}\norm{F}_{L^2_TL^{2_*,2}},\\
\label{lemma_proof_1_4}
\norm{v(x)\Gamma_0 ^*F}_{L^2_TL^{2}}&\le C \norm{v}_{L^{n,\infty}}\norm{F}_{L^2_TL^{2_*,2}}. 
\end{align}

\label{lemma_proof_2}
Let $w\in L^2(\R)$ be as in Theorem \ref{theorem_1}, $\rho>1/2$ and $v\in L^{n,\infty}(\R^n)$. Then there exists $C>0$, independent of $w,v$ and $T>0$, such that, for all $\psi\in L^2$ and simple function $F:\R\to \S(\R^n)$, one has
\begin{align}
\label{lemma_smoothing_2_1}
\norm{w(|x|)|D|^{1/2} e^{it\Delta}\psi}_{L^2_TL^2}
&\le C\norm{w}_{L^2(\R)}\norm{\psi}_{L^2},\\
\label{lemma_smoothing_2_2}
\norm{w(|x|)|D|^{1/2}\Gamma_0 F}_{L^2_TL^2}
&\le C \norm{w}_{L^2(\R)} \norm{F}_{L^2_TL^{2_*,2}},\\
\label{lemma_smoothing_2_3}
\norm{v(x)\Gamma_0 ^*F}_{L^2_TL^{2}}
&\le C \norm{v}_{L^{n,\infty}}\norm{w}_{L^2(\R)}\norm{w(|x|)^{-1}|D|^{-1/2}F}_{L^2_TL^{2}},\\

\label{lemma_smoothing_2_5}
\norm{\<x\>^{-\rho}|D|^{1/2} \Gamma_0 F}_{L^2_TL^2}
&\le C \norm{\<x\>^\rho |D|^{-1/2}F}_{L^2_TL^2},\\
\label{lemma_smoothing_2_6}
\norm{\<x\>^{-\rho}|D|^{1/2} \Gamma_0 F}_{L^2_TL^2}
&\le C \norm{F}_{L^2_TL^{2_*,2}},\\
\label{lemma_smoothing_2_7}
\norm{v(x)\Gamma_0 ^*F}_{L^2_TL^{2}}
&\le C \norm{v}_{L^{n,\infty}}\norm{\<x\>^{\rho}|D|^{-1/2}F}_{L^2_TL^{2}},\\
\label{lemma_smoothing_2_8}
\norm{v(x)\Gamma_0 F}_{L^2_TL^2}
&\le C \norm{v}_{L^{n,\infty}}\norm{\<x\>^\rho |D|^{-1/2}F}_{L^2_TL^{2}}.
\end{align}

proposition.raw:
\label{proposition_abstract_1}
{\rm (1)} $A$ is $H$-smooth with bound $a$ if and only if,  for any $\psi\in \H$, $e^{-itH}\psi$ belongs to $D(A)$ for a.e. $t\in \R$ and 
\begin{align}
\label{proposition_abstract_1_1}
\norm{Ae^{-itH}\psi}_{L^2(\R;\H)}
\le a\norm{\psi}. 
\end{align}
{\rm (2)} Suppose $A$ is $H$-supersmooth with bound $a$. Then, for any simple function $F:\R\to D(A^*)$ and $t\in \R$, $Ae^{-i(t-s)H}A^*F(s)$ is Bochner integrable in $s$ over $[0,t]$ (or $[t,0]$) and satisfies 
\begin{align}
\label{proposition_abstract_1_2}
\bignorm{e^{-|\ep t|}\int_0^t Ae^{-i(t-s)H}A^*F(s)ds}_{L^2(\R;\H)}\le a\norm{e^{-|\ep t|}F}_{L^2(\R;\H)}
\end{align}
for all $\ep\in \R$. Conversely, if the estimate \eqref{proposition_abstract_1_2}  holds for all simple function $F:\R\to D(A^*)$ and $|\ep|<\ep_0$ with some $\ep_0>0$, then $A$ is $H$-supersmooth with bound $a$.

