\label{proposition_abstract_2}
Let $\A,\B$ be two Banach spaces such that $(\A,\H)$ and $(\B,\H)$ are Banach couples.  
Suppose that $V_1$ is $H_0$-smooth and $V_2$ is both $H_0$-smooth and $H$-smooth. Consider the following series of estimates:  
\begin{align}
\label{proposition_abstract_2_1}
|\<\<e^{-itH_0}\psi,G\>\>_T|&\le s_1\norm{\psi}_{\H}\norm{G}_{L^2_T\B}, \\
\label{proposition_abstract_2_2}
|\<\<\Gamma_{H_0}F,G\>\>_T|&\le s_2\norm{F}_{L^2_T\A}\norm{G}_{L^2_T\B},\\\label{proposition_abstract_2_3}
\norm{V_1\Gamma_{H_0}^*G}_{L^2_T\H}&\le s_3\norm{G}_{L^2_T\B},\\
\label{proposition_abstract_2_4}
\norm{V_1\Gamma_{H_0}F}_{L^2_T\H}&\le s_4\norm{F}_{L^2_T\A},\\
\label{proposition_abstract_2_5}
\norm{V_2\Gamma_{H_0}F}_{L^2_T\H}&\le s_5\norm{F}_{L^2_T\A},\\
\label{proposition_abstract_2_6}
\norm{V_2e^{-itH}\psi}_{L^2_T\H}&\le s_6\norm{\psi}_{\H},\\
\label{proposition_abstract_2_7}
\norm{V_2\Gamma_HV_2^*\wtilde G}_{L^2_T\H}&\le s_7\norm{\wtilde G}_{L^2_T\H}. 
\end{align}
{\rm (1)} Suppose there exist constants $s_1,s_3,s_6>0$ such that \eqref{proposition_abstract_2_1}, \eqref{proposition_abstract_2_3} and \eqref{proposition_abstract_2_6} are satisfied for all $\psi\in \H$ and simple function $G:[-T,T]\to \H\cap \B$:
Then one has
$$
|\<\<e^{-itH}\psi,G\>\>_T|\le (s_1+s_3s_6)\norm{\psi}_{\H}\norm{G}_{L^2_T\B}
$$
for all $\psi\in \H$ and simple function $G:[-T,T]\to \H\cap \B$. \\
{\rm (2)} Suppose that there exist constants $s_2,s_3,s_4,s_5,s_7>0$ such that \eqref{proposition_abstract_2_2}, \eqref{proposition_abstract_2_3}, \eqref{proposition_abstract_2_4}, \eqref{proposition_abstract_2_5} and \eqref{proposition_abstract_2_7} hold for all simple functions $F:[-T,T]\to \H\cap \A$, $G:[-T,T]\to \H\cap \B$ and $\wtilde G:[-T,T]\to D(H)$. Then one has
$$
|\<\<\Gamma_{H}F,G\>\>_T|\le (s_2+s_3s_5+s_3s_4s_7)\norm{F}_{L^2_T\A}\norm{G}_{L^2_T\B}
$$
for all simple functions $F:[-T,T]\to \H\cap \A$ and $G:[-T,T]\to \H\cap \B$.

proof.raw:
We give the proof in detail for the sake of self-containedness. Let us first show the first statement. The Duhamel formula implies
\begin{align}
\label{proof_proposition_abstract_2_1}
\<e^{-itH}\psi,\varphi\>=\<e^{-itH_0}\psi,\varphi\>-i\int_0^t\<V_2e^{-irH}\psi,V_1e^{-i(r-t)H_0}\varphi\>dr,\quad \psi,\varphi\in L^2. 
\end{align}
Plugging $\varphi=G(t)$, integrating over $t\in [-T,T]$ and using Fubini's theorem, we learn by the formula \eqref{adjoint_1} of the adjoint $\Gamma_{H_0}^*$ that
$$
\<\<e^{-itH}\psi,G\>\>_T=\<\<e^{-itH_0}\psi,G\>\>_T-i\<\<V_2e^{-itH}\psi,V_1\Gamma_{H_0}^*G\>\>_T. 
$$
Applying \eqref{proposition_abstract_2_1}, \eqref{proposition_abstract_2_3} and \eqref{proposition_abstract_2_6}, we then obtain the first assertion (1). 


In order to prove the  second assertion (2), we replace $t$ by $t-s$ and plug $\psi=F(s),\varphi=G(t)$ and integrate over $s\in [0,t]$ in \eqref{proof_proposition_abstract_2_1} to obtain
\begin{align*}
\<\Gamma_HF(t),G(t)\>
&=\<\Gamma_{H_0}F(t),G(t)\>-i\int_0^t\int_s^t\<V_2e^{-i(\tau-s)H}F(s),V_1e^{-i(\tau-t)H_0}G(t)\>d\tau ds\\
&=\<\Gamma_{H_0}F(t),G(t)\>-i\int_0^t\<V_2\Gamma_HF(\tau),V_1e^{-i(\tau-t)H_0}G(t)\>d\tau.
\end{align*}
As above, integrating in $t\in [-T,T]$ and using  \eqref{adjoint_1} implies
\begin{align}
\label{proof_proposition_abstract_2_2}
\<\<\Gamma_HF,G\>\>_T=\<\<\Gamma_{H_0}F,G\>\>_T-i\<\<V_2\Gamma_HF,V_1\Gamma_{H_0}^*G\>\>_T. 
\end{align}
Exchanging the roles of $H$ and $H_0$, we also obtain
\begin{align}
\label{proof_proposition_abstract_2_3}
\<\<\Gamma_HF,G\>\>_T=\<\<\Gamma_{H_0}F,G\>\>_T-i\<\<V_1\Gamma_{H_0}F,V_2\Gamma_{H}^*G\>\>_T
\end{align}
Now applying  \eqref{proposition_abstract_2_2}, \eqref{proposition_abstract_2_3} to \eqref{proof_proposition_abstract_2_2} implies
\begin{align}
\label{proof_proposition_abstract_2_4}
|\<\<\Gamma_HF,G\>\>_T|\le s_2\norm{F}_{L^2_T\A}\norm{G}_{L^2_T\B}+s_3\norm{V_2\Gamma_HF}_{L^2_T\H}\norm{G}_{L^2_T\B}.
\end{align}
It remains to deal with $\norm{V_2\Gamma_HF}_{L^2_T\H}=\sup_{\norm{\widetilde G}_{L^2_T\H}=1}|\<\<V_2\Gamma_HF,\widetilde G\>\>_T|$. Since $D(H)$ is dense in $\H$, we may assume $\widetilde G(t)\in D(H)$. Then, taking $D(H)\subset D(V_2^*)$ into account, we use \eqref{proof_proposition_abstract_2_3} with $G=V_2^*\widetilde G$, \eqref{proposition_abstract_2_4}, \eqref{proposition_abstract_2_5} and \eqref{proposition_abstract_2_7} to obtain
$
|\<\<V_2\Gamma_HF,\widetilde G\>\>_T|\le (s_5+s_4s_7)\norm{F}_{L^2_T\A}
$
which, together with \eqref{proof_proposition_abstract_2_3}, gives us the second assertion. This completes the proof.

Let us set $V_1=|x|V$ and $V_2=|x|^{-1}$. By Sobolev's inequality \eqref{Sobolev}, 
$$
\norm{V_jf}_{L^2}\le C \norm{V_j}_{L^{n,\infty}}\norm{f}_{L^{2^*,2}}\le C \norm{V_j}_{L^{n,\infty}}\norm{\nabla f}_{L^2}
$$
and hence $D(V_j)\supset \H^1\supset D(\Delta)\cup D(H)$. Moreover,  \eqref{lemma_proof_1_1} and Proposition \ref{proposition_abstract_1} (1) show that both $V_1$ and $V_2$ are $\Delta$-smooth. On the other hand, Propositions \ref{proposition_abstract_1} and  \ref{proposition_smoothing_3} show
\begin{align}
\label{proof_1_1}
\norm{V_2e^{-itH}\psi}_{L^2_TL^2}\le C \norm{\psi}_{L^2}
\end{align}
uniformly in $T>0$. Let $\B$ the completion of $C_0^\infty$ with respect to the norm $\norm{w(|x|)^{-1}|D|^{-1/2}f}_{L^2}$. By virtue of \eqref{lemma_smoothing_2_1}, \eqref{lemma_smoothing_2_3} and \eqref{proof_1_1}, one can use Proposition \ref{proposition_abstract_2} with $H_0=-\Delta$, $H=-\Delta+V$ and this $\B$ to obtain
$$
|\<\<e^{-itH}\psi,G\>\>_T|\le C \norm{w}_{L^2(\R)}\norm{\psi}_{L^2}\norm{G}_{\B}
$$
for all $\psi\in L^2$ and simple function $G:[-T,T]\to \S$ uniformly in $T>0$. Then the desired estimate follows from density and duality arguments.

We use the same decomposition $V=V_1V_2$ as above. Since $V_2$ is $H$-supersmooth, we learn by  Proposition \ref{proposition_abstract_1} and a remark after Lemma \ref{lemma_abstract_2} that 
\begin{align}
\label{proof_2_1}
\norm{V_2\Gamma_HV_2\wtilde G}_{L^2_TL^2}\le C\norm{\wtilde G}_{L^2_TL^2}
\end{align}
for all simple function $\wtilde G:\R\to D(V_2)$ with the constant $C$ independent of $T$ and $\wtilde G$. By virtue of \eqref{lemma_proof_1_1}--\eqref{lemma_proof_1_4}, \eqref{lemma_smoothing_2_1} with $w=\<x\>^{-\rho}$, \eqref{lemma_smoothing_2_5}--\eqref{lemma_smoothing_2_8} with $v\in \{V_1,V_2\}$, \eqref{proof_1_1} and \eqref{proof_2_1}, we can use Proposition \ref{proposition_abstract_2} with $\A,\B\in \{\dot\H^{-1/2,\rho},L^{2_*,2}\}$ to obtain 
\begin{align*}
|\<\<e^{-itH}\psi,G\>\>_T|\le C \norm{\psi}_{L^2}\norm{G}_{L^2_T\B},\quad
|\<\<\Gamma_HF,G\>\>_T|\le C \norm{F}_{L^2_T\A}\norm{G}_{L^2_T\B}
\end{align*}
uniformly in $T>0$, $\psi\in L^2$ and simple functions $F,G:\R\to\S$. Then the assertion follows from density of simple functions $F:\R\to\S$ in $L^2_T\A$ and $L^2_T\B$ and the formula \eqref{solution}.

