and \ref{theorem_2}}
\label{section_proof}
Let $H=-\Delta+V(x)$ be as in Theorem \ref{theorem_1}. This section is devoted to the proof of the main theorems. In what follows we use a standard notation
$2^*=2n/(n-2)$, 
$2_*=2n/(n+2)$.
 We write $\Gamma_0=\Gamma_{-\Delta}$. 
Let us first recall various estimates for the free Schr\"odinger equation. 



\begin{lemma}
\label{lemma_proof_1}
There exists $C>0$ such that, for any $v\in L^{n,\infty}(\R^n)$ and $T>0$, 
\begin{align}
\label{lemma_proof_1_1}
\norm{e^{it\Delta}\psi}_{L^2_TL^{2^*,2}}&\le C\norm{\psi}_{L^2},\\
\label{lemma_proof_1_2}
\norm{\Gamma_0 F}_{L^2_TL^{2^*,2}}&\le C \norm{F}_{L^2_TL^{2_*,2}},\\
\label{lemma_proof_1_3}
\norm{v(x)\Gamma_0 F}_{L^2_TL^{2}}&\le C \norm{v}_{L^{n,\infty}}\norm{F}_{L^2_TL^{2_*,2}},\\
\label{lemma_proof_1_4}
\norm{v(x)\Gamma_0 ^*F}_{L^2_TL^{2}}&\le C \norm{v}_{L^{n,\infty}}\norm{F}_{L^2_TL^{2_*,2}}. 
\end{align}
\end{lemma}

\begin{proof}
\eqref{lemma_proof_1_1} and \eqref{lemma_proof_1_2} are endpoint Strichartz estimates proved by \cite[Theorem 10.1]{KeTa}. The latter two estimates follow from \eqref{lemma_proof_1_2}, H\"older's inequality \eqref{Holder} and the duality.
\end{proof}


\begin{lemma}
\label{lemma_proof_2}
Let $w\in L^2(\R)$ be as in Theorem \ref{theorem_1}, $\rho>1/2$ and $v\in L^{n,\infty}(\R^n)$. Then there exists $C>0$, independent of $w,v$ and $T>0$, such that, for all $\psi\in L^2$ and simple function $F:\R\to \S(\R^n)$, one has
\begin{align}
\label{lemma_smoothing_2_1}
\norm{w(|x|)|D|^{1/2} e^{it\Delta}\psi}_{L^2_TL^2}
&\le C\norm{w}_{L^2(\R)}\norm{\psi}_{L^2},\\
\label{lemma_smoothing_2_2}
\norm{w(|x|)|D|^{1/2}\Gamma_0 F}_{L^2_TL^2}
&\le C \norm{w}_{L^2(\R)} \norm{F}_{L^2_TL^{2_*,2}},\\
\label{lemma_smoothing_2_3}
\norm{v(x)\Gamma_0 ^*F}_{L^2_TL^{2}}
&\le C \norm{v}_{L^{n,\infty}}\norm{w}_{L^2(\R)}\norm{w(|x|)^{-1}|D|^{-1/2}F}_{L^2_TL^{2}},\\

\label{lemma_smoothing_2_5}
\norm{\<x\>^{-\rho}|D|^{1/2} \Gamma_0 F}_{L^2_TL^2}
&\le C \norm{\<x\>^\rho |D|^{-1/2}F}_{L^2_TL^2},\\
\label{lemma_smoothing_2_6}
\norm{\<x\>^{-\rho}|D|^{1/2} \Gamma_0 F}_{L^2_TL^2}
&\le C \norm{F}_{L^2_TL^{2_*,2}},\\
\label{lemma_smoothing_2_7}
\norm{v(x)\Gamma_0 ^*F}_{L^2_TL^{2}}
&\le C \norm{v}_{L^{n,\infty}}\norm{\<x\>^{\rho}|D|^{-1/2}F}_{L^2_TL^{2}},\\
\label{lemma_smoothing_2_8}
\norm{v(x)\Gamma_0 F}_{L^2_TL^2}
&\le C \norm{v}_{L^{n,\infty}}\norm{\<x\>^\rho |D|^{-1/2}F}_{L^2_TL^{2}}.
\end{align}
\end{lemma}


\begin{proof}
Let us first consider \eqref{lemma_smoothing_2_1}. When $n=1$, it was proved by \cite{KPV}  that
$$
\sup_{x\in \R}\norm{|D_x|^{1/2}e^{it\partial_x^2}f}_{L^2(\R_t)}\le C \norm{f}_{L^2(\R_x)}
$$
which, together with the unitarity of $e^{it\Delta_{\widehat{x}_j}}$ in $L^2(\R^{n-1})$, implies
$$
\norm{|D_j|^{1/2} e^{it\Delta}\psi}_{L^\infty_{x_j}L^2_TL^2_{\widehat x_j}}
\le C\norm{\psi}_{L^2},\quad j=1,2,...,n,
$$
uniformly in $T>0$, where $\widehat x_j=(x_1,...,x_{j-1},x_{j+1},...,x_n)\in \R^{n-1}$ and $D_j=-i\partial_{x_j}$. \eqref{lemma_smoothing_2_1} then is derived from this estimate as follows. Let $\{C_j(\xi)\}$ be a conical partition of unity on $\R^n$ so that $
I=\sum_{j=1}^n C_j(\xi),
$
where $C_j\in C^\infty(\R^n\setminus\{0\})$ such that $\supp C_j\subset\{2|\xi_j|>|\xi|\}$ and $\partial_\xi^\alpha C_j(\xi)=O(|\xi|^{-|\alpha|})$. If we set 
$
\wtilde C_j(\xi)=C_j(\xi)|\xi|^{1/2}|\xi_j|^{-1/2}
$ then $\wtilde C_j$ also satisfies $\partial_\xi^\alpha C_j(\xi)=O(|\xi|^{-|\alpha|})$ and
$
|\xi|^{1/2}=\sum_{j=1}^n\wtilde C_j(\xi)|\xi_j|^{1/2}. 
$
Since $w(|x|)^2$ belongs to the Muckenhoupt $A_2$-class, $\wtilde C_j(D)$ is bounded on a weighted space $L^2(\R^n,w(|x|)^2dx)$ by weighted Mikhlin's multiplier theorem (see \cite{KuWh}). Thus we conclude that
\begin{align*}
\norm{w(|x|)|D|^{1/2}e^{it\Delta}\psi}_{L^2_TL^2}^2
&\le \sum_{j=1}^n\norm{w(|x|)\wtilde C_j(D)|D_{j}|^{1/2}e^{it\Delta}\psi}_{L^2_TL^2}^2\\
&\le C\sum_{j=1}^n\norm{w(|x|)|D_{j}|^{1/2}e^{it\Delta}\psi}_{L^2_TL^2}^2\\

&\le C\sum_{j=1}^n\norm{w}_{L^2(\R)}^2\norm{|D_{j}|^{1/2}e^{it\Delta}\psi}_{L^\infty_{x_j}L^2_TL^2_{\widehat x_j}}^2\\
&\le C \norm{w}_{L^2(\R)}^2\norm{\psi}_{L^2}^2
\end{align*}
uniformly in $T>0$, where we used the properties $w(|x|)\le C_jw(x_j)$ and $w\in L^2(\R)$ in the third line. Next, by the same argument as above, \eqref{lemma_smoothing_2_2} follows from the following estimate
\begin{align*}
\norm{|D_j|^{1/2}\Gamma_0 F}_{L^\infty_{x_j}L^2_TL^2_{\widehat x_j}}
\le C \norm{F}_{L^2_TL^{2_*,2}}.
\end{align*}
which is a slight generalization of \cite[Lemma 4]{IoKe}, in which the same estimate with $L^{2_*,2}$ replaced by $L^{2_*}$ was proved. Although the proof is essentially same as that of \cite[Lemma 4]{IoKe}, we briefly recall its strategy for reader's convenience. Without loss of generality, we may assume $j=1$. Then it suffices to show 
\begin{align}
\label{lemma_magnetic_1_2}
\sup_{x_1}\norm{|D_j|^{1/2}\wtilde\Gamma_0 F}_{L^2_TL^2_{\widehat x_1}}\le C\norm{F}_{L^2_TL^{2_*,2}},
\end{align}
where $\wtilde \Gamma_0 $ is defined by
$$
\wtilde \Gamma_0 F(t):=\int_{-\infty}^te^{i(t-s)\Delta}F(s)ds.
$$
Indeed, the corresponding estimate for $\Gamma_0 -\wtilde\Gamma_0 $ follows from \eqref{lemma_smoothing_2_1} and the dual estimate of \eqref{lemma_proof_1_1}. The only difference from the proof of \cite[Lemma 4]{IoKe} is an interpolation step. While they used the complex interpolation, we will use a real interpolation technique as in \cite[Section 6]{KeTa}. Let $I_{\pm}=\mathbf1_{\pm}(D_1)|D_1|^{1/2}\wtilde\Gamma_0 $, where $\mathbf 1_\pm(t)=1$ for $\pm t\ge0$ and $\mathbf 1_\pm(t)=0$ for $\mp t\ge0$. 
It suffices to show that $I_{+}$ is bounded from $L^2_TL^{2_*,2}$ to $L^2_TL^2_{\widehat x_1}$ uniformly in $x_1$ since the proof for $I_{-}$ being analogous. By the $TT^*$ argument, $I_{+}\in \mathbb B(L^2_TL^{2_*,2},L^2_TL^2_{\widehat x_1})$ if $I_{+}^*I_{+}$ is bounded from $L^2_TL^{2_*,2}$ to $L^2_TL^{2^*,2}$. Hence, if we define a bilinear form $I$ by$$
I(F,G):=\iint \<I_{+}F(s,\cdot),I_{+}G(t,\cdot)\>dsdt
$$
then it suffices to show that 
\begin{align}
\label{lemma_magnetic_1_3}
|I(F,G)|\le C\norm{F}_{L^2_TL^{2_*,2}}\norm{G}_{L^2_TL^{2_*,2}}
\end{align}
uniformly in $x_1$ and $T>0$. It was shown by \cite{IoKe} that $I_{+}^*I_{+}$ is bounded on $L^2(\R^n)$ and the kernel of $I_{+}^*I_{+}$, denoted by $K_{+}(t,s,x,y)$, satisfies the dispersive estimate:
$$
|K_{+}(t,s,x,y)|\le C|t-s|^{-n/2},\quad t\neq s.
$$
We then decompose $I(F,G)$ as
$$
I(F,G)=\sum_{k\in\Z}I_k(F,G),\ I_k(F,G):=\iint_{t-2^{k+1}}^{t-2^k} \<I_{+}F(s,\cdot),I_{+}G(t,\cdot)\>dsdt. 
$$
By using the same argument as in \cite[Lemma 4.1]{KeTa}, we see that 
\begin{align*}
|I_k(F,G)|\le  C2^{-k\beta(a,b)}\norm{F}_{L^2_TL^{a'}}\norm{G}_{L^2_TL^{b'}},\quad \beta(a,b)=\frac n2-1-\frac n2(\frac1a-\frac1b)
\end{align*}
uniformly in $k\in \Z$, where $(a,b)$ satisfies one of the following conditions:
$$
\text{(i)\ \ $\frac 1a=\frac 1b=0$;\quad (ii)\ \ $\frac{n-1}{2n}\le \frac1a \le \frac12$ and $\frac 1b=\frac12$;\quad (iii)\ \ $\frac{n-1}{2n}\le \frac1b \le \frac12$ and $\frac 1a=\frac12$. }
$$
In other words, a vector valued sequence $(I_k)_{k\in \Z}$ is bounded from $L^2_TL^{a'}_x\times L^2_TL^{b'}_x$ to $\ell_{\beta(a,b)}^\infty$, where $\ell^p_s=L^p(\Z, 2^{js}dj)$ is a weighted $\ell^p$ space with the counting measure $dj$. Then \eqref{lemma_magnetic_1_3} follows from the technique by \cite[Section 6]{KeTa} based on a bilinear real interpolation. 

The estimate \eqref{lemma_smoothing_2_3} follows from the dual estimate of \eqref{lemma_smoothing_2_2} and H\"older's inequality  \eqref{Holder}. For \eqref{lemma_smoothing_2_5}, we refer to \cite{Chi}. \eqref{lemma_smoothing_2_6} and \eqref{lemma_smoothing_2_7} follow from \eqref{lemma_smoothing_2_2} and \eqref{lemma_smoothing_2_3} since $\<x\>^{-\rho}$ satisfies the condition on $w$ in Theorem \ref{theorem_1}. In order to derive \eqref{lemma_smoothing_2_8}, we observe from the formula \eqref{adjoint_1} that $\Gamma_0 $ can be brought to the form
\begin{align*}
\Gamma_0 F(t)=-\Gamma_0 ^*F(t)\pm\Gamma_0 ^{0}F(t)+\Gamma_0 ^{\mp}F(t)
\end{align*}
for $\pm t\ge0$, where 
$$
\Gamma_0 ^{0}F(t)=\int_{-T}^Te^{-i(t-s)H}F(s)ds,\quad
\Gamma_0 ^{\pm}F(t)=\int_0^{\pm T}e^{-i(t-s)H}F(s)ds. 
$$
Then the desired estimate for $\Gamma_0 ^*$ is nothing but \eqref{lemma_smoothing_2_6}; the desired estimates for $\Gamma_0 ^{0}$ and $\Gamma_0 ^{\mp}$ follow from \eqref{lemma_proof_1_1}, the dual estimate of \eqref{lemma_smoothing_2_1} with $w=\<x\>^{-\rho}$ and H\"older's inequality  \eqref{Holder}. 
\end{proof}

The following fact, proved by \cite[Theorem 1.6 and (1.23)]{BVZ} (see also \cite[Theorem 6.1 and Appendix B]{BoMi}), also  plays an important role.

\begin{proposition}
\label{proposition_smoothing_3}
Let $n\ge3$ and $V$ satisfy Assumption \ref{assumption_A}. Then $|x|^{-1}$ is $H$-supersmooth.
\end{proposition}

We are in a position to show the main theorems. 


\begin{proof}[Proof of Theorem \ref{theorem_1}]
Let us set $V_1=|x|V$ and $V_2=|x|^{-1}$. By Sobolev's inequality \eqref{Sobolev}, 
$$
\norm{V_jf}_{L^2}\le C \norm{V_j}_{L^{n,\infty}}\norm{f}_{L^{2^*,2}}\le C \norm{V_j}_{L^{n,\infty}}\norm{\nabla f}_{L^2}
$$
and hence $D(V_j)\supset \H^1\supset D(\Delta)\cup D(H)$. Moreover,  \eqref{lemma_proof_1_1} and Proposition \ref{proposition_abstract_1} (1) show that both $V_1$ and $V_2$ are $\Delta$-smooth. On the other hand, Propositions \ref{proposition_abstract_1} and  \ref{proposition_smoothing_3} show
\begin{align}
\label{proof_1_1}
\norm{V_2e^{-itH}\psi}_{L^2_TL^2}\le C \norm{\psi}_{L^2}
\end{align}
uniformly in $T>0$. Let $\B$ the completion of $C_0^\infty$ with respect to the norm $\norm{w(|x|)^{-1}|D|^{-1/2}f}_{L^2}$. By virtue of \eqref{lemma_smoothing_2_1}, \eqref{lemma_smoothing_2_3} and \eqref{proof_1_1}, one can use Proposition \ref{proposition_abstract_2} with $H_0=-\Delta$, $H=-\Delta+V$ and this $\B$ to obtain
$$
|\<\<e^{-itH}\psi,G\>\>_T|\le C \norm{w}_{L^2(\R)}\norm{\psi}_{L^2}\norm{G}_{\B}
$$
for all $\psi\in L^2$ and simple function $G:[-T,T]\to \S$ uniformly in $T>0$. Then the desired estimate follows from density and duality arguments. 
\end{proof}


\begin{proof}[Proof of Theorem \ref{theorem_2}]
We use the same decomposition $V=V_1V_2$ as above. Since $V_2$ is $H$-supersmooth, we learn by  Proposition \ref{proposition_abstract_1} and a remark after Lemma \ref{lemma_abstract_2} that 
\begin{align}
\label{proof_2_1}
\norm{V_2\Gamma_HV_2\wtilde G}_{L^2_TL^2}\le C\norm{\wtilde G}_{L^2_TL^2}
\end{align}
for all simple function $\wtilde G:\R\to D(V_2)$ with the constant $C$ independent of $T$ and $\wtilde G$. By virtue of \eqref{lemma_proof_1_1}--\eqref{lemma_proof_1_4}, \eqref{lemma_smoothing_2_1} with $w=\<x\>^{-\rho}$, \eqref{lemma_smoothing_2_5}--\eqref{lemma_smoothing_2_8} with $v\in \{V_1,V_2\}$, \eqref{proof_1_1} and \eqref{proof_2_1}, we can use Proposition \ref{proposition_abstract_2} with $\A,\B\in \{\dot\H^{-1/2,\rho},L^{2_*,2}\}$ to obtain 
\begin{align*}
|\<\<e^{-itH}\psi,G\>\>_T|\le C \norm{\psi}_{L^2}\norm{G}_{L^2_T\B},\quad
|\<\<\Gamma_HF,G\>\>_T|\le C \norm{F}_{L^2_T\A}\norm{G}_{L^2_T\B}
\end{align*}
uniformly in $T>0$, $\psi\in L^2$ and simple functions $F,G:\R\to\S$. Then the assertion follows from density of simple functions $F:\R\to\S$ in $L^2_T\A$ and $L^2_T\B$ and the formula \eqref{solution}. 
\end{proof}


